"""Auto-generated markdown post-mortem per incident."""
from __future__ import annotations

from datetime import datetime, timezone
from pathlib import Path

from .config import POLICY_ID, POLICY_TEXT, REPORTS_DIR


def write_report(incident: dict) -> str:
    REPORTS_DIR.mkdir(parents=True, exist_ok=True)
    ts = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")
    fname = f"incident-{incident['id']:04d}-{ts}.md"
    path = REPORTS_DIR / fname

    ev = incident.get("evidence") or {}
    lines = [
        f"# Incident {incident['id']:04d} — {incident['type'].replace('_', ' ').title()}",
        "",
        "> Auto-generated by Guardian. This is the artefact a real SRE would hand to",
        "> compliance the next morning. Every field below was captured live.",
        "",
        "## Summary",
        "",
        f"- **Type:** `{incident['type']}`",
        f"- **Status:** `{incident['status']}`",
        f"- **Detected at:** {incident['detected_at']}",
        f"- **Resolved at:** {incident.get('resolved_at') or 'in progress'}",
        f"- **Time to recovery (MTTR):** {incident.get('mttr_seconds') if incident.get('mttr_seconds') is not None else 'n/a'} s",
        f"- **Action taken:** `{incident.get('action') or 'n/a'}`",
        f"- **Blast radius (transactions scored while the incident was open):** {incident.get('blast_radius') or 0}",
        "",
        "## Why Guardian flagged it",
        "",
        incident.get("reasoning", "(no reasoning captured)"),
        "",
        "## Evidence",
        "",
        "```json",
    ]
    import json as _json

    lines.append(_json.dumps(ev, indent=2))
    lines += [
        "```",
        "",
        "## Governance",
        "",
        f"- **Policy applied:** `{POLICY_ID}` — {POLICY_TEXT}",
        "",
        "## Timeline",
        "",
        f"1. `{incident['detected_at']}` — Guardian raised the incident.",
        f"2. `{incident.get('resolved_at') or 'pending'}` — Recovery action `{incident.get('action') or 'n/a'}` completed.",
        "",
        "---",
        "*Generated by GuardianOps.*",
    ]
    path.write_text("\n".join(lines), encoding="utf-8")
    return str(path)
